/*
# Window Siphon · 窗口虹吸

窗口最小化时连续拉伸、收束到任务栏外沿，还原时反向展开。
Window Siphon 基于 MacOS Minimize Animation 的 Classic Genie 分支独立维护。
启用前请先禁用原版或旧 Classic Genie 模组，避免重复处理同一个窗口。

- 默认动画时长 **300 毫秒**，移动与收窄连续推进，仅展开接近原窗口时减速收尾。
- 收束点贴合任务栏外沿，窗口越贴近任务栏，底边起步收窄越柔和。
- 按对应任务栏项确定动画目标，不要求窗口具有关闭按钮、最小化按钮或标题栏。
- 保留系统捕获保护与用户排除列表；找不到可靠任务栏位置或无法取得有效截图时，回退正常窗口操作。
- 自动匹配窗口所在屏幕的刷新率，包括小数刷新率；每次动画重新读取。
- 自动模式按画布大小和刷新率选择 50–100% 动画分辨率，低分辨率纹理由 GPU 平滑放大。
- GPU 网格着色器完成形变，每帧更新 96 字节参数；圆角、柔和阴影及动态模糊随动画变化。
- 截图纹理可缓存到还原阶段，缓存容量有上限；空闲时没有动画渲染循环。
- 手动 100% 使用兼容渲染路径；GPU 不可用时自动回退。兼容路径不提供网格路径的圆角与阴影增强。
- 最小化先合成完整首帧，再隐藏真实窗口并开始计时；首帧超时回退系统操作。
- 重复事件合并；反向操作、窗口销毁或状态变化会取消旧动画，并恢复窗口显示。
- 截图使用 PrintWindow，不创建 Windows Graphics Capture 会话。
- 启动画面为空或纯黑时进行有上限的退避重试；仍不可用时正常显示窗口。
- WinUI 和系统窗口宿主按需监听显示事件，复用隐藏窗口可以再次播放启动动画。
- 设置项汉化，保留窗口还原、排除程序、自动隐藏任务栏和实验性多显示器支持。

启动动画与多显示器支持默认关闭。动画使用静态截图，半透明背景与实时模糊
可能无法由应用截图保留，也不会随动画更新。具体应用兼容性可能不同。

原模组作者：Abdullah Masood，MIT 许可。
截图、任务栏 UI Automation 定位及自动隐藏处理源自 Potassiumuncher 的贡献。
Window Siphon 维护：SinCircle。修改包括动画曲线与轮廓、中文设置、任务栏边界修复、
刷新率与渲染分辨率自适应、GPU 网格渲染、窗口生命周期与启动截图处理。
*/
// ==/WindhawkModReadme==

// ==WindhawkModSettings==
/*
- duration_ms: 300
  $name: 动画时长（毫秒）
  $description: 最小化和还原动画的持续时间，范围 50–2000，默认 300。收起和展开起步直接推进，仅展开末段减速收尾。
- render_scale_percent: 0
  $name: 动画分辨率（%，0 为自动）
  $description: 0 根据画布大小和屏幕刷新率自动选择 50–100%；也可输入 50–100。75% 表示宽高各为 75%，像素量约 56%。只降低运动画面清晰度，不改变窗口大小和动画时长。
- motion_blur: true
  $name: 启用动态模糊
  $description: 随运动速度变化的轻量模糊，起止保持清晰。关闭可降低大窗口的渲染开销。
- open_animation: true
  $name: 启用窗口还原动画
  $description: 从任务栏还原窗口时，播放反向神灯动画。
- launch_animation: false
  $name: 启用应用启动动画（实验性）
  $description: 普通应用窗口出现时播放动画；工具面板、受保护窗口、无效截图或未找到可靠任务栏位置时自动回退。
- multi_monitor: false
  $name: 多显示器支持（实验性）
  $description: 使用窗口所在显示器的任务栏作为动画目标；关闭时使用主显示器。
- unhide_taskbar: true
  $name: 动画期间显示自动隐藏的任务栏
  $description: 最小化时临时展开自动隐藏的任务栏，动画结束后恢复隐藏。
- unhide_duration_ms: 300
  $name: 任务栏保持显示时间（毫秒）
  $description: 自动隐藏任务栏临时展开的时长，范围 0–5000，默认 300。
- excluded_programs: [""]
  $name: 排除的程序
  $description: 每项填写一个程序名，例如 WindowsTerminal.exe。按窗口所属程序匹配，无论动画从哪个进程触发。
*/
// ==/WindhawkModSettings==

