static bool GeniePrepareWarpShaders(GenieGpuDevice* state){ // state mutex held
    if(state->shaderAttempted)return state->warpVertex&&state->warpPixel&&state->warpRaster;
    state->shaderAttempted=true;
    HRESULT hr=state->device->CreateVertexShader(GenieWarpVertexCode,sizeof(GenieWarpVertexCode),nullptr,&state->warpVertex);
    if(SUCCEEDED(hr))hr=state->device->CreatePixelShader(GenieWarpPixelCode,sizeof(GenieWarpPixelCode),nullptr,&state->warpPixel);
    D3D11_RASTERIZER_DESC raster{};raster.FillMode=D3D11_FILL_SOLID;raster.CullMode=D3D11_CULL_NONE;raster.DepthClipEnable=TRUE;
    if(SUCCEEDED(hr))hr=state->device->CreateRasterizerState(&raster,&state->warpRaster);
    return SUCCEEDED(hr);
}

